import { useCallback, useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import Button from '@mui/material/Button';
import { fetchMovies, fetchScreenings } from '../../api/client';
import type { Movie, Screening } from '../../api/types';
import { DayPicker } from './DayPicker';
import { resolveSelectedDate } from './dayPicker';
import './movie-list.scss';

type LoadState = 'loading' | 'error' | 'loaded';

export function MovieList() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedDate = resolveSelectedDate(searchParams.get('date'));

  const [state, setState] = useState<LoadState>('loading');
  const [movies, setMovies] = useState<Movie[]>([]);
  const [screenings, setScreenings] = useState<Screening[]>([]);

  const load = useCallback(() => {
    setState('loading');
    Promise.all([fetchMovies(), fetchScreenings()])
      .then(([loadedMovies, loadedScreenings]) => {
        setMovies(loadedMovies);
        setScreenings(loadedScreenings);
        setState('loaded');
      })
      .catch(() => setState('error'));
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const screeningsByMovie = new Map<number, Screening[]>();
  for (const screening of screenings) {
    if (screening.date !== selectedDate) continue;
    const list = screeningsByMovie.get(screening.movieId) ?? [];
    list.push(screening);
    screeningsByMovie.set(screening.movieId, list);
  }
  for (const list of screeningsByMovie.values()) {
    list.sort((a, b) => a.time.localeCompare(b.time));
  }

  const moviesToShow = movies.filter((movie) => (screeningsByMovie.get(movie.id)?.length ?? 0) > 0);

  return (
    <div className="movie-list-page">
      <DayPicker
        selectedDate={selectedDate}
        onSelectDate={(iso) => setSearchParams({ date: iso })}
      />

      {state === 'loading' && <div data-testid="movies-loading">Loading…</div>}

      {state === 'error' && (
        <div data-testid="movies-error">
          Failed to load movies
          <Button data-testid="movies-retry-button" onClick={load}>
            Retry
          </Button>
        </div>
      )}

      {state === 'loaded' && moviesToShow.length === 0 && (
        <div data-testid="movies-empty">No screenings on this day</div>
      )}

      {state === 'loaded' && moviesToShow.length > 0 && (
        <div data-testid="movie-list">
          {moviesToShow.map((movie) => (
            <div key={movie.id} className="movie-card" data-testid="movie-card" data-movie-id={movie.id}>
              <div data-testid="movie-title" className="movie-card__title">
                {movie.title}
              </div>
              <div data-testid="movie-genre">{movie.genre}</div>
              <div data-testid="movie-runtime">{movie.runtimeMinutes} min</div>
              <div data-testid="movie-format">{movie.format}</div>
              <div className="movie-card__screenings">
                {screeningsByMovie.get(movie.id)!.map((screening) => (
                  <Button
                    key={screening.id}
                    data-testid="screening-button"
                    data-screening-id={screening.id}
                    variant="outlined"
                    onClick={() => navigate(`/screenings/${screening.id}/seats`)}
                  >
                    {screening.time}
                  </Button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useNavigate } from 'react-router-dom';
import Button from '@mui/material/Button';
import { useTicketScreen } from '../../booking/useTicketScreen';
import { TicketItem } from '../../booking/ticketItems';
import { formatPrice } from '../../format';
import './summary.scss';

export function Summary() {
  const navigate = useNavigate();
  const { screeningId, booking, updateBooking, screening, movie, items, total, ready } = useTicketScreen();

  if (!ready || !booking || !screening || !movie) return null;

  function handleRemove(item: TicketItem) {
    const remaining = booking!.seats.filter((seatId) => !item.seatIds.includes(seatId));
    updateBooking((current) => ({ ...current, seats: remaining }));
    if (remaining.length === 0) {
      navigate(`/screenings/${screeningId}/seats`);
    }
  }

  return (
    <div className="summary-page">
      <h1 data-testid="summary-title">Your tickets</h1>
      <div data-testid="summary-list" className="summary-list">
        {items.map((item) => (
          <div key={item.key} data-testid="summary-item" className="summary-item">
            <div data-testid="summary-item-title">{movie.title}</div>
            <div data-testid="summary-item-datetime">
              {screening.date} {screening.time}
            </div>
            <div data-testid="summary-item-row">{item.row}</div>
            <div data-testid="summary-item-seat">{item.description}</div>
            <div data-testid="summary-item-price">{formatPrice(item.price)}</div>
            <Button data-testid="summary-item-remove-button" onClick={() => handleRemove(item)}>
              Remove
            </Button>
          </div>
        ))}
      </div>
      <div data-testid="summary-total">Total: {formatPrice(total)}</div>
      <div className="summary-actions">
        <Button data-testid="back-button" variant="outlined" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
          Back
        </Button>
        <Button data-testid="confirm-button" variant="contained" onClick={() => navigate(`/screenings/${screeningId}/checkout`)}>
          Confirm
        </Button>
      </div>
    </div>
  );
}

