import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';
import { writeFileSync } from 'node:fs';

const CHROME = '/opt/ms-playwright/chromium-1234/chrome-linux/chrome';
const PORT = 9333;

function launchChrome() {
  return spawn(
    CHROME,
    [
      '--headless=new',
      '--no-sandbox',
      '--disable-gpu',
      `--remote-debugging-port=${PORT}`,
      '--window-size=1280,720',
      'about:blank',
    ],
    { stdio: 'ignore' },
  );
}

async function waitForDevtools() {
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (res.ok) return;
    } catch {
      /* retry */
    }
    await delay(500);
  }
  throw new Error('devtools not ready');
}

async function newTab() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
  return res.json();
}

class CDP {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 0;
    this.pending = new Map();
    this.consoleErrors = [];
    this.ws.addEventListener('message', (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject } = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
      if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
        this.consoleErrors.push(msg.params.args.map((a) => a.value ?? a.description).join(' '));
      }
      if (msg.method === 'Runtime.exceptionThrown') {
        this.consoleErrors.push(JSON.stringify(msg.params.exceptionDetails));
      }
    });
  }
  ready() {
    return new Promise((resolve, reject) => {
      this.ws.addEventListener('open', resolve, { once: true });
      this.ws.addEventListener('error', reject, { once: true });
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async evaluate(expression) {
    const result = await this.send('Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    if (result.exceptionDetails) {
      throw new Error(`Evaluate failed: ${JSON.stringify(result.exceptionDetails)}`);
    }
    return result.result.value;
  }
  async waitFor(expression, timeoutMs = 10000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      const value = await this.evaluate(expression).catch(() => false);
      if (value) return value;
      await delay(200);
    }
    throw new Error(`Timed out waiting for: ${expression}`);
  }
  async screenshot(path) {
    const { data } = await this.send('Page.captureScreenshot', { format: 'png' });
    writeFileSync(path, Buffer.from(data, 'base64'));
  }
}

async function fillInput(cdp, selector, value) {
  await cdp.evaluate(`
    (function() {
      const el = document.querySelector(${JSON.stringify(selector)});
      const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(el, ${JSON.stringify(value)});
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('blur', { bubbles: true }));
      return true;
    })()
  `);
}

async function main() {
  const chrome = launchChrome();
  process.on('exit', () => chrome.kill());
  await waitForDevtools();
  const tab = await newTab();
  const cdp = new CDP(tab.webSocketDebuggerUrl);
  await cdp.ready();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');

  const log = (...args) => console.log(...args);

  // 1. Movie list
  await cdp.send('Page.navigate', { url: 'http://localhost:4200/' });
  await cdp.waitFor(`document.querySelector('[data-testid="movie-list"], [data-testid="movies-empty"], [data-testid="movies-error"]') !== null`, 15000);
  await cdp.screenshot('/tmp/01-movie-list.png');
  log('movie-list screenshot taken');

  const movieCardCount = await cdp.evaluate(`document.querySelectorAll('[data-testid="movie-card"]').length`);
  log('movie cards:', movieCardCount);

  if (movieCardCount === 0) {
    log('No movie cards for today; trying tomorrow via datepicker is complex, checking other days via day-button');
    const dayButtons = await cdp.evaluate(`[...document.querySelectorAll('[data-testid="day-button"]')].map(b => b.dataset.date)`);
    log('day buttons:', dayButtons);
  }

  // click first screening button
  const screeningId = await cdp.evaluate(`
    (function() {
      const btn = document.querySelector('[data-testid="screening-button"]');
      if (!btn) return null;
      return btn.dataset.screeningId;
    })()
  `);
  log('first screening id found:', screeningId);

  if (!screeningId) {
    log('No screening button found on default day; aborting flow here.');
    await cdp.screenshot('/tmp/01b-no-screenings.png');
    console.log('CONSOLE_ERRORS', JSON.stringify(cdp.consoleErrors));
    chrome.kill();
    return;
  }

  await cdp.evaluate(`document.querySelector('[data-testid="screening-button"]').click()`);
  await cdp.waitFor(`document.querySelector('[data-testid="seat-map"]') !== null`, 15000);
  await cdp.screenshot('/tmp/02-seat-map.png');
  const seatCount = await cdp.evaluate(`document.querySelectorAll('[data-testid="seat"]').length`);
  const couchCount = await cdp.evaluate(`document.querySelectorAll('[data-testid="couch"]').length`);
  log('seat count:', seatCount, 'couch count:', couchCount);

  // select first 2 available seats and 1 available couch
  const selectResult = await cdp.evaluate(`
    (function() {
      const seats = [...document.querySelectorAll('[data-testid="seat"][data-state="available"]')].slice(0, 2);
      seats.forEach(s => s.click());
      const couch = document.querySelector('[data-testid="couch"][data-state="available"]');
      if (couch) couch.click();
      return { seatsClicked: seats.length, couchClicked: !!couch };
    })()
  `);
  log('selection result:', JSON.stringify(selectResult));
  await delay(200);
  const selectedCount = await cdp.evaluate(`document.querySelector('[data-testid="selected-seats-count"]').textContent`);
  log('selected-seats-count text:', selectedCount);
  await cdp.screenshot('/tmp/03-seats-selected.png');

  await cdp.evaluate(`document.querySelector('[data-testid="continue-button"]').click()`);
  await cdp.waitFor(`document.querySelector('[data-testid="summary-list"]') !== null`, 15000);
  await cdp.screenshot('/tmp/04-summary.png');
  const summaryTotal = await cdp.evaluate(`document.querySelector('[data-testid="summary-total"]').textContent`);
  log('summary total:', summaryTotal);

  await cdp.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await cdp.waitFor(`document.querySelector('[data-testid="checkout-title"]') !== null`, 15000);
  await cdp.screenshot('/tmp/05-checkout-empty.png');

  await fillInput(cdp, '[data-testid="first-name-input"]', 'Anna');
  await fillInput(cdp, '[data-testid="last-name-input"]', 'Kowalska');
  await fillInput(cdp, '[data-testid="email-input"]', 'anna.kowalska@example.com');
  await fillInput(cdp, '[data-testid="confirm-email-input"]', 'anna.kowalska@example.com');
  await fillInput(cdp, '[data-testid="phone-input"]', '123456789');
  await cdp.evaluate(`document.querySelector('[data-testid="terms-checkbox"]').click()`);
  await delay(200);
  await cdp.screenshot('/tmp/06-checkout-filled.png');

  const payLabel = await cdp.evaluate(`document.querySelector('[data-testid="pay-button"]').textContent`);
  log('pay button label:', payLabel);

  await cdp.evaluate(`document.querySelector('[data-testid="pay-button"]').click()`);
  await cdp.waitFor(`document.querySelector('[data-testid="confirmation-heading"]') !== null`, 15000);
  await cdp.screenshot('/tmp/07-confirmation.png');
  const confirmationMessage = await cdp.evaluate(`document.querySelector('[data-testid="confirmation-message"]').textContent`);
  log('confirmation message:', confirmationMessage);

  console.log('CONSOLE_ERRORS', JSON.stringify(cdp.consoleErrors));

  chrome.kill();
}

main().catch((err) => {
  console.error('DRIVE_FAILED', err);
  process.exit(1);
});

