   - **apps/cinescope/src/booking/useTicketScreen.ts** (created) — shared hook used by both Summary and Checkout pages, implementing the route-guard + data-loading logic in a single `useEffect` (combined deliberately to avoid firing an unnecessary fetch when the booking guard already fails):
     ```ts
     export function useTicketScreen(): TicketScreen {
       const { id } = useParams<{ id: string }>();
       const screeningId = Number(id);
       const navigate = useNavigate();
       const [booking, setBooking] = useState<Booking | null>(null);
       const [screening, setScreening] = useState<Screening | null>(null);
       const [movie, setMovie] = useState<Movie | null>(null);

       useEffect(() => {
         const existing = loadBooking();
         if (!isUsableUnpaidBooking(existing, screeningId)) {
           navigate('/', { replace: true });
           return;
         }
         setBooking(existing);
         let cancelled = false;
         fetchScreening(screeningId)
           .then((loadedScreening) =>
             fetchMovie(loadedScreening.movieId).then((loadedMovie) => {
               if (cancelled) return;
               setScreening(loadedScreening);
               setMovie(loadedMovie);
             }),
           )
           .catch(() => { if (!cancelled) navigate('/', { replace: true }); });
         return () => { cancelled = true; };
         // eslint-disable-next-line react-hooks/exhaustive-deps
       }, [screeningId]);

       function updateBooking(updater: (current: Booking) => Booking) {
         setBooking((prev) => {
           if (!prev) return prev;
           const next = updater(prev);
           saveBooking(next);
           return next;
         });
       }

       const items = booking ? computeTicketItems(booking.seats) : [];
       const total = totalPrice(items);
       return { screeningId, booking, updateBooking, screening, movie, items, total, ready: !!booking && !!screening && !!movie };
     }
     ```

   - **apps/cinescope/src/toast/ToastContext.tsx** (created) — `ToastProvider` using local state `{message,key}` with a `useEffect`-driven 4000ms `setTimeout` keyed by `toast` (so each new `showToast` call resets the timer); renders MUI `Snackbar open={toast!==null}` containing `Alert severity="info" variant="filled" data-testid="toast"`. `useToast()` hook returns the `showToast` function from context (default no-op).

   - **apps/cinescope/src/app/app.tsx** (edited) — wraps `Routes` in `ToastProvider`; routes: `/` → `MovieList`, `/screenings/:id/seats` → `SeatSelection`, `/screenings/:id/summary` → `Summary`, `/screenings/:id/checkout` → `Checkout`, `/confirmation` → `Confirmation`, `*` → `<Navigate to="/" replace />`.

